G_PlayerReborn :: proc(player: int) {
	frags: [MAXPLAYERS]int
	p := &players[player]

	frags = p.frags
	killcount := p.killcount
	itemcount := p.itemcount
	secretcount := p.secretcount

	p^ = {}

	p.frags = frags
	p.killcount = killcount
	p.itemcount = itemcount
	p.secretcount = secretcount

