M_ReadSaveStrings :: proc() {
	name: [256]u8

	for i := 0; i < load_end; i += 1 {
		if M_CheckParm("-cdrom") != 0 {
			libc.sprintf(&name[0], "c:\\doomdata\\" + SAVEGAMENAME + "%d.dsg", i32(i))
		} else {
			libc.sprintf(&name[0], SAVEGAMENAME + "%d.dsg", i32(i))
		}

		f := libc.fopen(cstring(&name[0]), "rb")
		if f == nil {
			libc.strcpy(&savegamestrings[i][0], EMPTYSTRING)
			LoadMenu[i].status = 0
			continue
		}
		libc.fread(&savegamestrings[i][0], 1, SAVESTRINGSIZE, f)
		libc.fclose(f)
		LoadMenu[i].status = 1
	}
}

M_DrawLoad :: proc() {
