			other = sides[check.sidenum[1]].sector
		} else {
			other = sides[check.sidenum[0]].sector
		}

		if (int(check.flags) & ML_SOUNDBLOCK) != 0 {
			if soundblocks == 0 {
				P_RecursiveSound(other, 1)
			}
		} else {
			P_RecursiveSound(other, soundblocks)
		}
	}
}

