	dl: divline_t
	P_MakeDivline(ld, &dl)
	frac := P_InterceptVector(&trace, &dl)

	if frac < 0 {
		return true
	}

	if earlyout && frac < FRACUNIT && ld.backsector == nil {
		return false
	}

	intercept_p[0].frac = frac
	intercept_p[0].isaline = true
	intercept_p[0].d.line = ld
	intercept_p = &intercept_p[1]

	return true
}

PIT_AddThingIntercepts :: proc(thing: ^mobj_t) -> boolean {
	tracepositive := (trace.dx ~ trace.dy) > 0

	x1, y1, x2, y2: fixed_t
	if tracepositive {
		x1 = thing.x - thing.radius
		y1 = thing.y + thing.radius
		x2 = thing.x + thing.radius
		y2 = thing.y - thing.radius
	} else {
		x1 = thing.x - thing.radius
		y1 = thing.y - thing.radius
		x2 = thing.x + thing.radius
		y2 = thing.y + thing.radius
	}

	s1 := P_PointOnDivlineSide(x1, y1, &trace)
	s2 := P_PointOnDivlineSide(x2, y2, &trace)

	if s1 == s2 {
		return true
	}

	dl := divline_t{
		x = x1,
		y = y1,
		dx = x2 - x1,
		dy = y2 - y1,
	}

	frac := P_InterceptVector(&trace, &dl)

	if frac < 0 {
		return true
	}

	intercept_p[0].frac = frac
	intercept_p[0].isaline = false
	intercept_p[0].d.thing = thing
	intercept_p = &intercept_p[1]

	return true
}

P_TraverseIntercepts :: proc(func: traverser_t, maxfrac: fixed_t) -> boolean {
	count := int(uintptr(intercept_p) - uintptr(&intercepts[0])) / size_of(intercept_t)
	in_ptr: ^intercept_t = nil

	for count > 0 {
		count -= 1
		dist := fixed_t(MAXINT)
		for scan := ([^]intercept_t)(&intercepts[0]); scan != intercept_p; scan = &scan[1] {
			if scan[0].frac < dist {
				dist = scan[0].frac
				in_ptr = &scan[0]
			}
		}

		if dist > maxfrac {
			return true
		}

		if !func(in_ptr) {
			return false
		}

		in_ptr.frac = fixed_t(MAXINT)
	}

	return true
}

P_PathTraverse :: proc(x1_in: fixed_t, y1_in: fixed_t, x2_in: fixed_t, y2_in: fixed_t, flags: int, trav: traverser_t) -> boolean {
	x1 := x1_in
	y1 := y1_in
	x2 := x2_in
	y2 := y2_in

	earlyout = (flags & PT_EARLYOUT) != 0

	validcount += 1
	intercept_p = &intercepts[0]

	if ((x1 - bmaporgx) & (MAPBLOCKSIZE - 1)) == 0 {
		x1 += FRACUNIT
	}
	if ((y1 - bmaporgy) & (MAPBLOCKSIZE - 1)) == 0 {
		y1 += FRACUNIT
	}

	trace.x = x1
	trace.y = y1
	trace.dx = x2 - x1
	trace.dy = y2 - y1

	x1 -= bmaporgx
	y1 -= bmaporgy
	xt1 := int(x1 >> MAPBLOCKSHIFT)
	yt1 := int(y1 >> MAPBLOCKSHIFT)

	x2 -= bmaporgx
	y2 -= bmaporgy
	xt2 := int(x2 >> MAPBLOCKSHIFT)
	yt2 := int(y2 >> MAPBLOCKSHIFT)

	mapxstep: int
	mapystep: int
	partial: fixed_t
	xstep: fixed_t
	ystep: fixed_t

	if xt2 > xt1 {
		mapxstep = 1
		partial = FRACUNIT - ((x1 >> MAPBTOFRAC) & (FRACUNIT - 1))
		ystep = FixedDiv(y2 - y1, abs(x2 - x1))
	} else if xt2 < xt1 {
		mapxstep = -1
		partial = (x1 >> MAPBTOFRAC) & (FRACUNIT - 1)
		ystep = FixedDiv(y2 - y1, abs(x2 - x1))
	} else {
		mapxstep = 0
		partial = FRACUNIT
		ystep = 256 * FRACUNIT
	}

	yintercept := (y1 >> MAPBTOFRAC) + FixedMul(partial, ystep)

	if yt2 > yt1 {
		mapystep = 1
		partial = FRACUNIT - ((y1 >> MAPBTOFRAC) & (FRACUNIT - 1))
		xstep = FixedDiv(x2 - x1, abs(y2 - y1))
	} else if yt2 < yt1 {
		mapystep = -1
		partial = (y1 >> MAPBTOFRAC) & (FRACUNIT - 1)
		xstep = FixedDiv(x2 - x1, abs(y2 - y1))
	} else {
		mapystep = 0
		partial = FRACUNIT
		xstep = 256 * FRACUNIT
	}
	xintercept := (x1 >> MAPBTOFRAC) + FixedMul(partial, xstep)

	mapx := xt1
	mapy := yt1

	for count := 0; count < 64; count += 1 {
		if (flags & PT_ADDLINES) != 0 {
			if !P_BlockLinesIterator(mapx, mapy, PIT_AddLineIntercepts) {
				return false
			}
		}

		if (flags & PT_ADDTHINGS) != 0 {
			if !P_BlockThingsIterator(mapx, mapy, PIT_AddThingIntercepts) {
				return false
			}
		}

		if mapx == xt2 && mapy == yt2 {
			break
		}

		if int(yintercept >> FRACBITS) == mapy {
			yintercept += ystep
			mapx += mapxstep
		} else if int(xintercept >> FRACBITS) == mapx {
			xintercept += xstep
			mapy += mapystep
		}
	}

	return P_TraverseIntercepts(trav, FRACUNIT)
}
