	P_InitThinkers()

	W_Reload()

	if gamemode == .commercial {
		if map_num < 10 {
			libc.sprintf(&lumpname[0], "map0%i", i32(map_num))
		} else {
			libc.sprintf(&lumpname[0], "map%i", i32(map_num))
		}
	} else {
		lumpname[0] = 'E'
		lumpname[1] = u8('0' + episode)
