	P_LoadSegs(lumpnum + ML_SEGS)

	rejectmatrix = ([^]byte)(W_CacheLumpNum(lumpnum + ML_REJECT, PU_LEVEL))
	P_GroupLines()

	bodyqueslot = 0
	deathmatch_p = &deathmatchstarts[0]
	P_LoadThings(lumpnum + ML_THINGS)

	if deathmatch != 0 {
		for i := 0; i < MAXPLAYERS; i += 1 {
			if playeringame[i] {
