	Z_ChangeTag(sbar, PU_CACHE)
	Z_ChangeTag(faceback, PU_CACHE)

	for i := 0; i < ST_NUMFACES; i += 1 {
		Z_ChangeTag(faces[i], PU_CACHE)
	}
}

ST_unloadData :: proc() {
	ST_unloadGraphics()
}

ST_initData :: proc() {
	st_firsttime = true
	st_plr = &players[consoleplayer]

	st_clock = 0
