	dm_state = 1
	cnt_pause = TICRATE

	for i := 0; i < MAXPLAYERS; i += 1 {
		if playeringame[i] {
			for j := 0; j < MAXPLAYERS; j += 1 {
				if playeringame[j] {
					dm_frags[i][j] = 0
				}
			}
			dm_totals[i] = 0
		}
	}

	WI_initAnimatedBack()
}

WI_updateDeathmatchStats :: proc() {
	WI_updateAnimatedBack()

	if acceleratestage != 0 && dm_state != 4 {
		acceleratestage = 0
		for i := 0; i < MAXPLAYERS; i += 1 {
			if playeringame[i] {
				for j := 0; j < MAXPLAYERS; j += 1 {
					if playeringame[j] {
						dm_frags[i][j] = plrs[i].frags[j]
					}
				}
				dm_totals[i] = WI_fragSum(i)
			}
		}
		S_StartSound(nil, int(sfxenum_t.sfx_barexp))
		dm_state = 4
	}

	if dm_state == 2 {
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}

		stillticking := false

		for i := 0; i < MAXPLAYERS; i += 1 {
			if playeringame[i] {
				for j := 0; j < MAXPLAYERS; j += 1 {
					if playeringame[j] && dm_frags[i][j] != plrs[i].frags[j] {
						if plrs[i].frags[j] < 0 {
							dm_frags[i][j] -= 1
						} else {
							dm_frags[i][j] += 1
						}

						if dm_frags[i][j] > 99 {
							dm_frags[i][j] = 99
						}
						if dm_frags[i][j] < -99 {
							dm_frags[i][j] = -99
						}
						stillticking = true
					}
				}
				dm_totals[i] = WI_fragSum(i)
				if dm_totals[i] > 99 {
					dm_totals[i] = 99
				}
				if dm_totals[i] < -99 {
					dm_totals[i] = -99
				}
			}
		}

		if !stillticking {
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			dm_state += 1
		}
	} else if dm_state == 4 {
		if acceleratestage != 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_slop))
			if gamemode == .commercial {
				WI_initNoState()
			} else {
				WI_initShowNextLoc()
			}
		}
	} else if (dm_state & 1) != 0 {
		cnt_pause -= 1
		if cnt_pause == 0 {
			dm_state += 1
			cnt_pause = TICRATE
		}
	}
}

WI_drawDeathmatchStats :: proc() {
