	WI_drawLF()

	V_DrawPatch(DM_TOTALSX - int(SHORT(total.width)) / 2, DM_MATRIXY - WI_SPACINGY + 10, FB, total)
	V_DrawPatch(DM_KILLERSX, DM_KILLERSY, FB, killers)
	V_DrawPatch(DM_VICTIMSX, DM_VICTIMSY, FB, victims)

	x := DM_MATRIXX + DM_SPACINGX
	y := DM_MATRIXY

