WI_checkForAccelerate :: proc() {
	for i := 0; i < MAXPLAYERS; i += 1 {
		player := &players[i]
		if playeringame[i] {
			if (player.cmd.buttons & BT_ATTACK) != 0 {
				if player.attackdown == 0 {
					acceleratestage = 1
				}
				player.attackdown = 1
			} else {
				player.attackdown = 0
			}
			if (player.cmd.buttons & BT_USE) != 0 {
				if player.usedown == 0 {
					acceleratestage = 1
				}
				player.usedown = 1
			} else {
				player.usedown = 0
			}
		}
	}
}

WI_Ticker :: proc() {
	bcnt += 1

	if bcnt == 1 {
		if gamemode == .commercial {
			S_ChangeMusic(int(musicenum_t.mus_dm2int), 1)
		} else {
			S_ChangeMusic(int(musicenum_t.mus_inter), 1)
		}
	}

	WI_checkForAccelerate()

	switch wi_state {
	case .StatCount:
		if deathmatch != 0 {
			WI_updateDeathmatchStats()
		} else if netgame {
			WI_updateNetgameStats()
		} else {
			WI_updateStats()
		}
	case .ShowNextLoc:
		WI_updateShowNextLoc()
	case .NoState:
		WI_updateNoState()
	}
}

WI_loadData :: proc() {
	name: [9]u8

