		}
	}

	bg = (^patch_t)(W_CacheLumpName(cstring(&name[0]), PU_CACHE))
	V_DrawPatch(0, 0, 1, bg)

	if gamemode == .commercial {
		NUMCMAPS = 32
		lnames = ([^]^patch_t)(Z_Malloc(size_of(^patch_t) * NUMCMAPS, PU_STATIC, nil))
		for i := 0; i < NUMCMAPS; i += 1 {
