			lnames[i] = (^patch_t)(W_CacheLumpName(cstring(&name[0]), PU_STATIC))
		}
	} else {
		lnames = ([^]^patch_t)(Z_Malloc(size_of(^patch_t) * NUMMAPS, PU_STATIC, nil))
		for i := 0; i < NUMMAPS; i += 1 {
			libc.sprintf(&name[0], "WILV%d%d", i32(wbs.epsd), i32(i))
			lnames[i] = (^patch_t)(W_CacheLumpName(cstring(&name[0]), PU_STATIC))
