AM_getIslope :: proc(ml: ^mline_t, is: ^islope_t) {
	dy := ml.a.y - ml.b.y
	dx := ml.b.x - ml.a.x
	if dy == 0 {
		is.islp = dx < 0 ? -MAXINT : MAXINT
	} else {
		is.islp = FixedDiv(dx, dy)
	}
	if dx == 0 {
		is.slp = dy < 0 ? -MAXINT : MAXINT
	} else {
		is.slp = FixedDiv(dy, dx)
	}
}

AM_activateNewScale :: proc() {
	m_x += m_w / 2
	m_y += m_h / 2
	m_w = FTOM(f_w)
	m_h = FTOM(f_h)
	m_x -= m_w / 2
	m_y -= m_h / 2
	m_x2 = m_x + m_w
	m_y2 = m_y + m_h
}

