AM_restoreScaleAndLoc :: proc() {
	m_w = old_m_w
	m_h = old_m_h
	if followplayer == 0 {
		m_x = old_m_x
		m_y = old_m_y
	} else {
		m_x = plr.mo.x - m_w / 2
		m_y = plr.mo.y - m_h / 2
	}
	m_x2 = m_x + m_w
	m_y2 = m_y + m_h

	scale_mtof = FixedDiv(fixed_t(i32(f_w) << FRACBITS), m_w)
	scale_ftom = FixedDiv(FRACUNIT, scale_mtof)
}

