d_main.odin
```odin
// Based on id Software's linuxdoom-1.10 (GNU GPL)
package main

import "core:c/libc"

BGCOLOR :: 7
FGCOLOR :: 8

wadfiles: [MAXWADFILES]cstring

devparm: boolean
nomonsters: boolean
respawnparm: boolean
fastparm: boolean
drone: boolean
singletics: boolean = false

startskill: skill_t
startepisode: int
startmap: int
autostart: boolean

debugfile: ^libc.FILE
advancedemo: boolean

wadfile: [1024]u8
mapdir: [1024]u8
basedefault: [1024]u8

events: [MAXEVENTS]event_t
eventhead: int
eventtail: int

wipegamestate: gamestate_t = .GS_DEMOSCREEN

d_viewactivestate: boolean = false
d_menuactivestate: boolean = false
d_inhelpscreensstate: boolean = false
d_fullscreen: boolean = false
d_oldgamestate: gamestate_t = gamestate_t(-1)
d_borderdrawcount: int = 0

demosequence: int
pagetic: int
pagename: cstring
title: [128]u8

D_PostEvent :: proc(ev: ^event_t) {
	events[eventhead] = ev^
	eventhead += 1
	eventhead &= MAXEVENTS - 1
}

D_ProcessEvents :: proc() {
	if gamemode == .commercial && W_CheckNumForName("map01") < 0 {
		return
	}

	for ; eventtail != eventhead; eventtail = (eventtail + 1) & (MAXEVENTS - 1) {
		ev := &events[eventtail]
		if M_Responder(ev) {
			continue
		}
		G_Responder(ev)
	}
}

D_Display :: proc() {
	if nodrawers {
		return
	}

	redrawsbar := false

	if setsizeneeded {
		R_ExecuteSetViewSize()
		d_oldgamestate = gamestate_t(-1)
		d_borderdrawcount = 3
	}

	wipe: boolean
	if gamestate != wipegamestate {
		wipe = true
		wipe_StartScreen(0, 0, SCREENWIDTH, SCREENHEIGHT)
	} else {
		wipe = false
	}

	if gamestate == .GS_LEVEL && gametic != 0 {
		HU_Erase()
	}

	switch gamestate {
	case .GS_LEVEL:
		if gametic == 0 {
			break
		}
		if automapactive {
			AM_Drawer()
		}
		if wipe || (viewheight != 200 && d_fullscreen) {
			redrawsbar = true
		}
		if d_inhelpscreensstate && !inhelpscreens {
			redrawsbar = true
		}
		ST_Drawer(viewheight == 200, redrawsbar)
		d_fullscreen = viewheight == 200
	case .GS_INTERMISSION:
		WI_Drawer()
	case .GS_FINALE:
		F_Drawer()
	case .GS_DEMOSCREEN:
		D_PageDrawer()
	}

	I_UpdateNoBlit()

	if gamestate == .GS_LEVEL && !automapactive && gametic != 0 {
		R_RenderPlayerView(&players[displayplayer])
	}

	if gamestate == .GS_LEVEL && gametic != 0 {
		HU_Drawer()
	}

	if gamestate != d_oldgamestate && gamestate != .GS_LEVEL {
		I_SetPalette(([^]byte)(W_CacheLumpName("PLAYPAL", PU_CACHE)))
	}

	if gamestate == .GS_LEVEL && d_oldgamestate != .GS_LEVEL {
		d_viewactivestate = false
		R_FillBackScreen()
	}

	if gamestate == .GS_LEVEL && !automapactive && scaledviewwidth != 320 {
		if menuactive || d_menuactivestate || !d_viewactivestate {
			d_borderdrawcount = 3
		}
		if d_borderdrawcount != 0 {
			R_DrawViewBorder()
			d_borderdrawcount -= 1
		}
	}

	d_menuactivestate = menuactive
	d_viewactivestate = viewactive
	d_inhelpscreensstate = inhelpscreens
	d_oldgamestate = gamestate
	wipegamestate = gamestate

	if paused {
		y: int
		if automapactive {
			y = 4
		} else {
			y = viewwindowy + 4
		}
		V_DrawPatchDirect(viewwindowx + (scaledviewwidth - 68) / 2, y, 0, (^patch_t)(W_CacheLumpName("M_PAUSE", PU_CACHE)))
	}

	M_Drawer()
	NetUpdate()

	if !wipe {
		I_FinishUpdate()
		return
	}

	wipe_EndScreen(0, 0, SCREENWIDTH, SCREENHEIGHT)

	wipestart := I_GetTime() - 1

	for {
		nowtime: int
		tics: int
		for {
			nowtime = I_GetTime()
			tics = nowtime - wipestart
			if tics != 0 {
				break
			}
		}
		wipestart = nowtime
		done := wipe_ScreenWipe(wipe_Melt, 0, 0, SCREENWIDTH, SCREENHEIGHT, tics)
		I_UpdateNoBlit()
		M_Drawer()
		I_FinishUpdate()
		if done != 0 {
			break
		}
	}
}

D_DoomLoop :: proc() {
	if demorecording {
		G_BeginRecording()
	}

	if M_CheckParm("-debugfile") != 0 {
		filename: [20]u8
		libc.sprintf(&filename[0], "debug%i.txt", i32(consoleplayer))
		libc.printf("debug output to: %s\n", &filename[0])
		debugfile = libc.fopen(cstring(&filename[0]), "w")
	}

	I_InitGraphics()

	for {
		I_StartFrame()

		if singletics {
			I_StartTic()
			D_ProcessEvents()
			G_BuildTiccmd(&netcmds[consoleplayer][maketic % BACKUPTICS])
			if advancedemo {
				D_DoAdvanceDemo()
			}
			M_Ticker()
			G_Ticker()
			gametic += 1
			maketic += 1
		} else {
			TryRunTics()
		}

		S_UpdateSounds(players[consoleplayer].mo)
		D_Display()
		I_UpdateSound()
		I_SubmitSound()
	}
}

D_PageTicker :: proc() {
	pagetic -= 1
	if pagetic < 0 {
		D_AdvanceDemo()
	}
}

D_PageDrawer :: proc() {
	V_DrawPatch(0, 0, 0, (^patch_t)(W_CacheLumpName(pagename, PU_CACHE)))
}

D_AdvanceDemo :: proc() {
	advancedemo = true
}

D_DoAdvanceDemo :: proc() {
	players[consoleplayer].playerstate = .PST_LIVE
	advancedemo = false
	usergame = false
	paused = false
	gameaction = .ga_nothing

	if gamemode == .retail {
		demosequence = (demosequence + 1) % 7
	} else {
		demosequence = (demosequence + 1) % 6
	}

	switch demosequence {
	case 0:
		if gamemode == .commercial {
			pagetic = 35 * 11
		} else {
			pagetic = 170
		}
		gamestate = .GS_DEMOSCREEN
		pagename = "TITLEPIC"
		if gamemode == .commercial {
			S_StartMusic(int(musicenum_t.mus_dm2ttl))
		} else {
			S_StartMusic(int(musicenum_t.mus_intro))
		}
	case 1:
		G_DeferedPlayDemo("demo1")
	case 2:
		pagetic = 200
		gamestate = .GS_DEMOSCREEN
		pagename = "CREDIT"
	case 3:
		G_DeferedPlayDemo("demo2")
	case 4:
		gamestate = .GS_DEMOSCREEN
		if gamemode == .commercial {
			pagetic = 35 * 11
			pagename = "TITLEPIC"
			S_StartMusic(int(musicenum_t.mus_dm2ttl))
		} else {
			pagetic = 200
			if gamemode == .retail {
				pagename = "CREDIT"
			} else {
				pagename = "HELP2"
			}
		}
	case 5:
		G_DeferedPlayDemo("demo3")
	case 6:
		G_DeferedPlayDemo("demo4")
	}
}

D_StartTitle :: proc() {
	gameaction = .ga_nothing
	demosequence = -1
	D_AdvanceDemo()
}

D_AddFile :: proc(file: cstring) {
	numwadfiles := 0
	for wadfiles[numwadfiles] != nil {
		numwadfiles += 1
	}

	newfile := ([^]u8)(libc.malloc(libc.strlen(file) + 1))
	libc.strcpy(newfile, file)
	wadfiles[numwadfiles] = cstring(newfile)
}

IdentifyVersion :: proc() {
	doomwaddir := libc.getenv("DOOMWADDIR")
	if doomwaddir == nil {
		doomwaddir = "."
	}

	doom2wad := ([^]u8)(libc.malloc(libc.strlen(doomwaddir) + 1 + 9 + 1))
