M_StringWidth :: proc(str: cstring) -> int {
	w := 0
	p := ([^]u8)(str)
	length := int(libc.strlen(str))
	for i := 0; i < length; i += 1 {
		c := int(libc.toupper(i32(p[i]))) - int(HU_FONTSTART)
		if c < 0 || c >= HU_FONTSIZE {
			w += 4
		} else {
			w += int(SHORT(hu_font[c].width))
		}
	}
	return w
}

M_StringHeight :: proc(str: cstring) -> int {
	height := int(SHORT(hu_font[0].height))
	h := height
	p := ([^]u8)(str)
	length := int(libc.strlen(str))
	for i := 0; i < length; i += 1 {
		if p[i] == '\n' {
			h += height
		}
	}
	return h
}

M_WriteText :: proc(x: int, y: int, str: cstring) {
	ch := ([^]u8)(str)
	cx := x
	cy := y

	for {
		c := int(ch[0])
		ch = &ch[1]
		if c == 0 {
			break
		}
		if c == '\n' {
			cx = x
			cy += 12
			continue
		}

		c = int(libc.toupper(i32(c))) - int(HU_FONTSTART)
		if c < 0 || c >= HU_FONTSIZE {
			cx += 4
			continue
		}

		w := int(SHORT(hu_font[c].width))
		if cx + w > SCREENWIDTH {
			break
		}
		V_DrawPatchDirect(cx, cy, 0, hu_font[c])
		cx += w
	}
}

M_Responder :: proc(ev: ^event_t) -> boolean {
	ch := -1

	if ev.type == .ev_joystick && m_joywait < I_GetTime() {
		if ev.data3 == -1 {
			ch = KEY_UPARROW
			m_joywait = I_GetTime() + 5
		} else if ev.data3 == 1 {
			ch = KEY_DOWNARROW
			m_joywait = I_GetTime() + 5
		}

		if ev.data2 == -1 {
			ch = KEY_LEFTARROW
			m_joywait = I_GetTime() + 2
		} else if ev.data2 == 1 {
			ch = KEY_RIGHTARROW
			m_joywait = I_GetTime() + 2
		}

		if (ev.data1 & 1) != 0 {
			ch = KEY_ENTER
			m_joywait = I_GetTime() + 5
		}
		if (ev.data1 & 2) != 0 {
			ch = KEY_BACKSPACE
			m_joywait = I_GetTime() + 5
		}
	} else {
		if ev.type == .ev_mouse && m_mousewait < I_GetTime() {
			m_mousey += ev.data3
			if m_mousey < m_lasty - 30 {
				ch = KEY_DOWNARROW
				m_mousewait = I_GetTime() + 5
				m_lasty -= 30
				m_mousey = m_lasty
			} else if m_mousey > m_lasty + 30 {
				ch = KEY_UPARROW
				m_mousewait = I_GetTime() + 5
				m_lasty += 30
				m_mousey = m_lasty
			}

			m_mousex += ev.data2
			if m_mousex < m_lastx - 30 {
				ch = KEY_LEFTARROW
				m_mousewait = I_GetTime() + 5
				m_lastx -= 30
				m_mousex = m_lastx
			} else if m_mousex > m_lastx + 30 {
				ch = KEY_RIGHTARROW
				m_mousewait = I_GetTime() + 5
				m_lastx += 30
				m_mousex = m_lastx
			}

			if (ev.data1 & 1) != 0 {
				ch = KEY_ENTER
				m_mousewait = I_GetTime() + 15
			}
			if (ev.data1 & 2) != 0 {
				ch = KEY_BACKSPACE
				m_mousewait = I_GetTime() + 15
			}
		} else if ev.type == .ev_keydown {
			ch = ev.data1
		}
	}

	if ch == -1 {
		return false
	}

	if saveStringEnter != 0 {
		switch ch {
		case KEY_BACKSPACE:
			if saveCharIndex > 0 {
				saveCharIndex -= 1
				savegamestrings[saveSlot][saveCharIndex] = 0
			}
		case KEY_ESCAPE:
			saveStringEnter = 0
			libc.strcpy(&savegamestrings[saveSlot][0], cstring(&saveOldString[0]))
		case KEY_ENTER:
			saveStringEnter = 0
			if savegamestrings[saveSlot][0] != 0 {
				M_DoSave(saveSlot)
			}
		case:
			ch = int(libc.toupper(i32(ch)))
			if ch != 32 {
				if ch - int(HU_FONTSTART) < 0 || ch - int(HU_FONTSTART) >= HU_FONTSIZE {
					break
				}
			}
			if ch >= 32 && ch <= 127 && saveCharIndex < SAVESTRINGSIZE - 1 && M_StringWidth(cstring(&savegamestrings[saveSlot][0])) < (SAVESTRINGSIZE - 2) * 8 {
				savegamestrings[saveSlot][saveCharIndex] = u8(ch)
				saveCharIndex += 1
				savegamestrings[saveSlot][saveCharIndex] = 0
			}
		}
		return true
	}

	if messageToPrint != 0 {
		if messageNeedsInput && !(ch == ' ' || ch == 'n' || ch == 'y' || ch == KEY_ESCAPE) {
			return false
		}

		menuactive = messageLastMenuActive != 0
		messageToPrint = 0
		if messageRoutine != nil {
			messageRoutine(ch)
		}

		menuactive = false
		S_StartSound(nil, int(sfxenum_t.sfx_swtchx))
		return true
	}

	if devparm && ch == KEY_F1 {
		G_ScreenShot()
		return true
	}

	if !menuactive {
		switch ch {
		case KEY_MINUS:
			if automapactive || chat_on {
				return false
			}
			M_SizeDisplay(0)
			S_StartSound(nil, int(sfxenum_t.sfx_stnmov))
			return true
		case KEY_EQUALS:
			if automapactive || chat_on {
				return false
			}
			M_SizeDisplay(1)
			S_StartSound(nil, int(sfxenum_t.sfx_stnmov))
			return true
		case KEY_F1:
			M_StartControlPanel()
			if gamemode == .retail {
				currentMenu = &ReadDef2
			} else {
				currentMenu = &ReadDef1
			}
			itemOn = 0
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			return true
		case KEY_F2:
			M_StartControlPanel()
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			M_SaveGame(0)
			return true
		case KEY_F3:
			M_StartControlPanel()
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			M_LoadGame(0)
			return true
		case KEY_F4:
			M_StartControlPanel()
			currentMenu = &SoundDef
			itemOn = sfx_vol
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			return true
		case KEY_F5:
			M_ChangeDetail(0)
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			return true
		case KEY_F6:
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			M_QuickSave()
			return true
		case KEY_F7:
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			M_EndGame(0)
			return true
		case KEY_F8:
			M_ChangeMessages(0)
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			return true
		case KEY_F9:
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			M_QuickLoad()
			return true
		case KEY_F10:
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			M_QuitDOOM(0)
			return true
		case KEY_F11:
			usegamma += 1
			if usegamma > 4 {
				usegamma = 0
			}
			players[consoleplayer].message = gammamsg[usegamma]
			I_SetPalette(([^]byte)(W_CacheLumpName("PLAYPAL", PU_CACHE)))
			return true
		}
	}

	if !menuactive {
		if ch == KEY_ESCAPE {
			M_StartControlPanel()
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
			return true
		}
		return false
	}

	switch ch {
	case KEY_DOWNARROW:
		for {
			if itemOn + 1 > currentMenu.numitems - 1 {
				itemOn = 0
			} else {
				itemOn += 1
			}
			S_StartSound(nil, int(sfxenum_t.sfx_pstop))
			if currentMenu.menuitems[itemOn].status != -1 {
				break
			}
		}
		return true
	case KEY_UPARROW:
		for {
			if itemOn == 0 {
				itemOn = currentMenu.numitems - 1
			} else {
				itemOn -= 1
			}
			S_StartSound(nil, int(sfxenum_t.sfx_pstop))
			if currentMenu.menuitems[itemOn].status != -1 {
				break
			}
		}
		return true
	case KEY_LEFTARROW:
		if currentMenu.menuitems[itemOn].routine != nil && currentMenu.menuitems[itemOn].status == 2 {
			S_StartSound(nil, int(sfxenum_t.sfx_stnmov))
			currentMenu.menuitems[itemOn].routine(0)
		}
		return true
	case KEY_RIGHTARROW:
		if currentMenu.menuitems[itemOn].routine != nil && currentMenu.menuitems[itemOn].status == 2 {
			S_StartSound(nil, int(sfxenum_t.sfx_stnmov))
			currentMenu.menuitems[itemOn].routine(1)
		}
		return true
	case KEY_ENTER:
		if currentMenu.menuitems[itemOn].routine != nil && currentMenu.menuitems[itemOn].status != 0 {
			currentMenu.lastOn = itemOn
			if currentMenu.menuitems[itemOn].status == 2 {
				currentMenu.menuitems[itemOn].routine(1)
				S_StartSound(nil, int(sfxenum_t.sfx_stnmov))
			} else {
				currentMenu.menuitems[itemOn].routine(int(itemOn))
				S_StartSound(nil, int(sfxenum_t.sfx_pistol))
			}
		}
		return true
	case KEY_ESCAPE:
		currentMenu.lastOn = itemOn
		M_ClearMenus()
		S_StartSound(nil, int(sfxenum_t.sfx_swtchx))
		return true
	case KEY_BACKSPACE:
		currentMenu.lastOn = itemOn
		if currentMenu.prevMenu != nil {
			currentMenu = currentMenu.prevMenu
			itemOn = currentMenu.lastOn
			S_StartSound(nil, int(sfxenum_t.sfx_swtchn))
		}
		return true
	case:
		for i := int(itemOn) + 1; i < int(currentMenu.numitems); i += 1 {
			if int(currentMenu.menuitems[i].alphaKey) == ch {
				itemOn = i16(i)
				S_StartSound(nil, int(sfxenum_t.sfx_pstop))
				return true
			}
		}
		for i := 0; i <= int(itemOn); i += 1 {
			if int(currentMenu.menuitems[i].alphaKey) == ch {
				itemOn = i16(i)
				S_StartSound(nil, int(sfxenum_t.sfx_pstop))
				return true
			}
		}
	}

	return false
}

M_StartControlPanel :: proc() {
	if menuactive {
		return
	}
	menuactive = true
	currentMenu = &MainDef
	itemOn = currentMenu.lastOn
}

M_Drawer :: proc() {
	str: [40]u8

	inhelpscreens = false

	if messageToPrint != 0 {
		start := 0
		y := 100 - M_StringHeight(messageString) / 2
		msg_bytes := ([^]u8)(messageString)
		for msg_bytes[start] != 0 {
			rem_len := int(libc.strlen(cstring(&msg_bytes[start])))
			i := 0
			for ; i < rem_len; i += 1 {
				if msg_bytes[start + i] == '\n' {
					libc.memset(&str[0], 0, 40)
					libc.strncpy(&str[0], cstring(&msg_bytes[start]), uint(i))
					start += i + 1
					break
				}
			}

			if i == rem_len {
				libc.strcpy(&str[0], cstring(&msg_bytes[start]))
				start += i
			}

			x := 160 - M_StringWidth(cstring(&str[0])) / 2
			M_WriteText(x, y, cstring(&str[0]))
			y += int(SHORT(hu_font[0].height))
		}
		return
	}

	if !menuactive {
		return
	}

	if currentMenu.routine != nil {
		currentMenu.routine()
	}

	x := int(currentMenu.x)
	y := int(currentMenu.y)
	max_items := int(currentMenu.numitems)

	for i := 0; i < max_items; i += 1 {
		if currentMenu.menuitems[i].name != nil && ((^u8)(currentMenu.menuitems[i].name))^ != 0 {
			V_DrawPatchDirect(x, y, 0, (^patch_t)(W_CacheLumpName(currentMenu.menuitems[i].name, PU_CACHE)))
		}
		y += LINEHEIGHT
	}

	V_DrawPatchDirect(x + SKULLXOFF, int(currentMenu.y) - 5 + int(itemOn) * LINEHEIGHT, 0, (^patch_t)(W_CacheLumpName(skullName[whichSkull], PU_CACHE)))
}

M_ClearMenus :: proc() {
	menuactive = false
}

M_SetupNextMenu :: proc(menudef: ^menu_t) {
	currentMenu = menudef
	itemOn = currentMenu.lastOn
}

M_Ticker :: proc() {
	skullAnimCounter -= 1
	if skullAnimCounter <= 0 {
		whichSkull ~= 1
		skullAnimCounter = 8
	}
}

M_Init :: proc() {
	currentMenu = &MainDef
	menuactive = false
	itemOn = currentMenu.lastOn
	whichSkull = 0
	skullAnimCounter = 10
	screenSize = screenblocks - 3
	messageToPrint = 0
	messageString = nil
	messageLastMenuActive = menuactive ? 1 : 0
	quickSaveSlot = -1

	switch gamemode {
	case .commercial:
		MainMenu[readthis_idx] = MainMenu[quitdoom_idx]
		MainDef.numitems -= 1
		MainDef.y += 8
		NewDef.prevMenu = &MainDef
		ReadDef1.routine = M_DrawReadThis1
		ReadDef1.x = 330
		ReadDef1.y = 165
		ReadMenu1[0].routine = M_FinishReadThis
	case .shareware, .registered:
		EpiDef.numitems -= 1
	case .retail, .indetermined:
	}
}
