	if i == 100 {
		I_Error("M_ScreenShot: Couldn't create a PCX")
	}

	WritePCXfile(cstring(&lbmname[0]), linear, SCREENWIDTH, SCREENHEIGHT, ([^]byte)(W_CacheLumpName("PLAYPAL", PU_CACHE)))
	players[consoleplayer].message = "screen shot"
