P_CheckMeleeRange :: proc(actor: ^mobj_t) -> boolean {
	if actor.target == nil {
		return false
	}

	pl := actor.target
	dist := P_AproxDistance(pl.x - actor.x, pl.y - actor.y)

	if dist >= MELEERANGE - 20 * FRACUNIT + fixed_t(pl.info.radius) {
		return false
	}

	if !P_CheckSight(actor, actor.target) {
		return false
	}

	return true
