	tryx := actor.x + fixed_t(actor.info.speed) * xspeed[actor.movedir]
	tryy := actor.y + fixed_t(actor.info.speed) * yspeed[actor.movedir]

	try_ok := P_TryMove(actor, tryx, tryy)

	if !try_ok {
		if (actor.flags & MF_FLOAT) != 0 && floatok {
