			an := R_PointToAngle2(actor.x, actor.y, player.mo.x, player.mo.y) - actor.angle
			if an > ANG90 && an < ANG270 {
				dist := P_AproxDistance(player.mo.x - actor.x, player.mo.y - actor.y)
				if dist > MELEERANGE {
