A_BossDeath :: proc(mo_raw: rawptr) {
	mo := (^mobj_t)(mo_raw)
	junk: line_t

	if gamemode == .commercial {
		if gamemap != 7 {
			return
		}
		if mo.type != .MT_FATSO && mo.type != .MT_BABY {
			return
		}
	} else {
		switch gameepisode {
		case 1:
			if gamemap != 8 { return }
			if mo.type != .MT_BRUISER { return }
		case 2:
			if gamemap != 8 { return }
			if mo.type != .MT_CYBORG { return }
		case 3:
			if gamemap != 8 { return }
			if mo.type != .MT_SPIDER { return }
		case 4:
			switch gamemap {
			case 6:
				if mo.type != .MT_CYBORG { return }
			case 8:
				if mo.type != .MT_SPIDER { return }
			case:
				return
			}
		case:
			if gamemap != 8 { return }
		}
	}

	i := 0
	for ; i < MAXPLAYERS; i += 1 {
		if playeringame[i] && players[i].health > 0 {
			break
		}
	}

	if i == MAXPLAYERS {
		return
	}

	for th := thinkercap.next; th != &thinkercap; th = th.next {
		if th.function.acp1 != P_MobjThinker {
			continue
		}
		mo2 := (^mobj_t)(th)
		if mo2 != mo && mo2.type == mo.type && mo2.health > 0 {
			return
		}
	}

	if gamemode == .commercial {
		if gamemap == 7 {
			if mo.type == .MT_FATSO {
				junk.tag = 666
				EV_DoFloor(&junk, .lowerFloorToLowest)
				return
			}
			if mo.type == .MT_BABY {
				junk.tag = 667
				EV_DoFloor(&junk, .raiseToTexture)
				return
			}
		}
	} else {
		switch gameepisode {
		case 1:
			junk.tag = 666
			EV_DoFloor(&junk, .lowerFloorToLowest)
			return
		case 4:
			switch gamemap {
			case 6:
				junk.tag = 666
				EV_DoDoor(&junk, .blazeOpen)
				return
			case 8:
				junk.tag = 666
				EV_DoFloor(&junk, .lowerFloorToLowest)
				return
			}
		}
	}

	G_ExitLevel()
}

