P_SetMobjState :: proc(mobj: ^mobj_t, state_in: statenum_t) -> boolean {
	state := state_in
	for {
		if state == .S_NULL {
			mobj.state = nil
			P_RemoveMobj(mobj)
			return false
		}

		st := &states[state]
		mobj.state = st
		mobj.tics = st.tics
		mobj.sprite = st.sprite
		mobj.frame = st.frame

		if st.action.acp1 != nil {
