	mo.momy = 0
	mo.momz = 0

	P_SetMobjState(mo, mobjinfo[mo.type].deathstate)

	mo.tics -= P_Random() & 3
	if mo.tics < 1 {
		mo.tics = 1
	}

	mo.flags &= ~int(MF_MISSILE)

	if mo.info.deathsound != .sfx_None {
		S_StartSound(mo, int(mo.info.deathsound))
