}

texpatch_t :: struct {
	originx: int,
	originy: int,
	patch:   int,
}

texture_t :: struct {
	name:       [8]u8,
	width:      i16,
	height:     i16,
	patchcount: i16,
	patches:    [1]texpatch_t,
}

firstflat: int
lastflat: int
numflats: int

firstpatch: int
lastpatch: int
numpatches: int

firstspritelump: int
lastspritelump: int
numspritelumps: int

numtextures: int
