	st_clock = 0
	st_chatstate = .StartChatState
	st_gamestate = .FirstPersonState

	st_statusbaron = true
	st_chat = false
	st_oldchat = false
	st_cursoron = false

	st_faceindex = 0
	st_palette = -1

	st_oldhealth = -1

	for i := 0; i < NUMWEAPONS; i += 1 {
		oldweaponsowned[i] = st_plr.weaponowned[i]
	}

	for i := 0; i < 3; i += 1 {
		keyboxes[i] = -1
	}

	STlib_init()
}

