		libc.memcpy(dest, src, uint(width))
		src = &src[width]
		dest = &dest[SCREENWIDTH]
	}
}

V_GetBlock :: proc(x: int, y: int, scrn: int, width: int, height_in: int, dest_in: [^]byte) {
