	V_DrawPatch(x, y, FB, percent)
	WI_drawNum(x, y, p, -1)
}

WI_drawTime :: proc(x_in: int, y: int, t: int) {
	x := x_in
	if t < 0 {
		return
	}

	if t <= 61 * 59 {
		div := 1
		for {
			n := (t / div) % 60
			x = WI_drawNum(x, y, n, 2) - int(SHORT(colon.width))
			div *= 60

			if div == 60 || (t / div) != 0 {
				V_DrawPatch(x, y, FB, colon)
			}

			if (t / div) == 0 {
				break
			}
		}
	} else {
		V_DrawPatch(x - int(SHORT(sucks.width)), y, FB, sucks)
	}
}

