WI_fragSum :: proc(playernum: int) -> int {
	frags := 0
	for i := 0; i < MAXPLAYERS; i += 1 {
		if playeringame[i] && i != playernum {
			frags += plrs[playernum].frags[i]
		}
	}
	frags -= plrs[playernum].frags[playernum]
	return frags
}

