	WI_initAnimatedBack()
}

WI_updateStats :: proc() {
	WI_updateAnimatedBack()

	if acceleratestage != 0 && sp_state != 10 {
		acceleratestage = 0
		cnt_kills[0] = (plrs[me].skills * 100) / wbs.maxkills
		cnt_items[0] = (plrs[me].sitems * 100) / wbs.maxitems
		cnt_secret[0] = (plrs[me].ssecret * 100) / wbs.maxsecret
		cnt_time = plrs[me].stime / TICRATE
		cnt_par = wbs.partime / TICRATE
		S_StartSound(nil, int(sfxenum_t.sfx_barexp))
		sp_state = 10
	}

	if sp_state == 2 {
		cnt_kills[0] += 2
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		if cnt_kills[0] >= (plrs[me].skills * 100) / wbs.maxkills {
			cnt_kills[0] = (plrs[me].skills * 100) / wbs.maxkills
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			sp_state += 1
		}
	} else if sp_state == 4 {
		cnt_items[0] += 2
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		if cnt_items[0] >= (plrs[me].sitems * 100) / wbs.maxitems {
			cnt_items[0] = (plrs[me].sitems * 100) / wbs.maxitems
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			sp_state += 1
		}
	} else if sp_state == 6 {
		cnt_secret[0] += 2
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		if cnt_secret[0] >= (plrs[me].ssecret * 100) / wbs.maxsecret {
			cnt_secret[0] = (plrs[me].ssecret * 100) / wbs.maxsecret
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			sp_state += 1
		}
	} else if sp_state == 8 {
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}

		cnt_time += 3
		if cnt_time >= plrs[me].stime / TICRATE {
			cnt_time = plrs[me].stime / TICRATE
		}

		cnt_par += 3
		if cnt_par >= wbs.partime / TICRATE {
			cnt_par = wbs.partime / TICRATE
			if cnt_time >= plrs[me].stime / TICRATE {
				S_StartSound(nil, int(sfxenum_t.sfx_barexp))
				sp_state += 1
			}
		}
	} else if sp_state == 10 {
		if acceleratestage != 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_sgcock))
			if gamemode == .commercial {
				WI_initNoState()
			} else {
				WI_initShowNextLoc()
			}
		}
	} else if (sp_state & 1) != 0 {
		cnt_pause -= 1
		if cnt_pause == 0 {
			sp_state += 1
			cnt_pause = TICRATE
		}
	}
}

WI_drawStats :: proc() {
	lh := (3 * int(SHORT(num[0].height))) / 2

