    attackrange = distance;
    linetarget = NULL;

    P_PathTraverse ( t1->x, t1->y,
		     x2, y2,
		     PT_ADDLINES|PT_ADDTHINGS,
		     PTR_AimTraverse );

    if (linetarget)
	return aimslope;

    return 0;
}


