	min_x = MAXINT
	min_y = MAXINT
	max_x = -MAXINT
	max_y = -MAXINT

	for i := 0; i < numvertexes; i += 1 {
		if vertexes[i].x < min_x {
			min_x = vertexes[i].x
		} else if vertexes[i].x > max_x {
			max_x = vertexes[i].x
		}

		if vertexes[i].y < min_y {
			min_y = vertexes[i].y
		} else if vertexes[i].y > max_y {
			max_y = vertexes[i].y
		}
	}

	max_w = max_x - min_x
	max_h = max_y - min_y

	min_w = 2 * PLAYERRADIUS
	min_h = 2 * PLAYERRADIUS

	a := FixedDiv(fixed_t(i32(f_w) << FRACBITS), max_w)
	b := FixedDiv(fixed_t(i32(f_h) << FRACBITS), max_h)

	min_scale_mtof = a < b ? a : b
	max_scale_mtof = FixedDiv(fixed_t(i32(f_h) << FRACBITS), 2 * PLAYERRADIUS)
}

AM_changeWindowLoc :: proc() {
	if m_paninc.x != 0 || m_paninc.y != 0 {
		followplayer = 0
		f_oldloc.x = MAXINT
	}

	m_x += m_paninc.x
	m_y += m_paninc.y

	if m_x + m_w/2 > max_x {
		m_x = max_x - m_w/2
	} else if m_x + m_w/2 < min_x {
		m_x = min_x - m_w/2
	}

	if m_y + m_h/2 > max_y {
		m_y = max_y - m_h/2
	} else if m_y + m_h/2 < min_y {
		m_y = min_y - m_h/2
	}

	m_x2 = m_x + m_w
	m_y2 = m_y + m_h
}

AM_initVariables :: proc() {
	st_notify := event_t{ type = .ev_keyup, data1 = AM_MSGENTERED }

	automapactive = true
	fb = screens[0]

	f_oldloc.x = MAXINT
	amclock = 0
	lightlev = 0

	m_paninc.x = 0
	m_paninc.y = 0
	ftom_zoommul = FRACUNIT
	mtof_zoommul = FRACUNIT

	m_w = FTOM(f_w)
	m_h = FTOM(f_h)

	pnum := consoleplayer
	if !playeringame[pnum] {
		for pnum = 0; pnum < MAXPLAYERS; pnum += 1 {
			if playeringame[pnum] {
				break
			}
		}
	}

	plr = &players[pnum]
	m_x = plr.mo.x - m_w/2
	m_y = plr.mo.y - m_h/2
	AM_changeWindowLoc()

	old_m_x = m_x
	old_m_y = m_y
	old_m_w = m_w
	old_m_h = m_h

	ST_Responder(&st_notify)
}

