	f_h = finit_height

	AM_clearMarks()

	AM_findMinMaxBoundaries()
	scale_mtof = FixedDiv(min_scale_mtof, fixed_t(0.7 * f64(FRACUNIT)))
	if scale_mtof > max_scale_mtof {
		scale_mtof = min_scale_mtof
	}
	scale_ftom = FixedDiv(FRACUNIT, scale_mtof)
}

AM_Stop :: proc() {
