AM_minOutWindowScale :: proc() {
	scale_mtof = min_scale_mtof
	scale_ftom = FixedDiv(FRACUNIT, scale_mtof)
	AM_activateNewScale()
}

AM_maxOutWindowScale :: proc() {
	scale_mtof = max_scale_mtof
	scale_ftom = FixedDiv(FRACUNIT, scale_mtof)
	AM_activateNewScale()
}

AM_Responder :: proc(ev: ^event_t) -> boolean {
	rc: boolean = false

	if !automapactive {
		if ev.type == .ev_keydown && ev.data1 == AM_STARTKEY {
			AM_Start()
			viewactive = false
			rc = true
		}
	} else if ev.type == .ev_keydown {
		rc = true
		switch ev.data1 {
		case AM_PANRIGHTKEY:
			if followplayer == 0 {
				m_paninc.x = FTOM(F_PANINC)
			} else {
				rc = false
			}
		case AM_PANLEFTKEY:
			if followplayer == 0 {
				m_paninc.x = -FTOM(F_PANINC)
			} else {
				rc = false
			}
		case AM_PANUPKEY:
			if followplayer == 0 {
				m_paninc.y = FTOM(F_PANINC)
			} else {
				rc = false
			}
		case AM_PANDOWNKEY:
			if followplayer == 0 {
				m_paninc.y = -FTOM(F_PANINC)
			} else {
				rc = false
			}
		case AM_ZOOMOUTKEY:
			mtof_zoommul = M_ZOOMOUT
			ftom_zoommul = M_ZOOMIN
		case AM_ZOOMINKEY:
			mtof_zoommul = M_ZOOMIN
			ftom_zoommul = M_ZOOMOUT
		case AM_ENDKEY:
			am_bigstate = 0
			viewactive = true
			AM_Stop()
		case AM_GOBIGKEY:
			am_bigstate = am_bigstate == 0 ? 1 : 0
			if am_bigstate != 0 {
				AM_saveScaleAndLoc()
				AM_minOutWindowScale()
			} else {
				AM_restoreScaleAndLoc()
			}
		case AM_FOLLOWKEY:
			followplayer = followplayer == 0 ? 1 : 0
			f_oldloc.x = MAXINT
			plr.message = followplayer != 0 ? AMSTR_FOLLOWON : AMSTR_FOLLOWOFF
		case AM_GRIDKEY:
			grid = grid == 0 ? 1 : 0
			plr.message = grid != 0 ? AMSTR_GRIDON : AMSTR_GRIDOFF
		case AM_MARKKEY:
			libc.sprintf(&am_buffer[0], "%s %d", AMSTR_MARKEDSPOT, i32(markpointnum))
			plr.message = cstring(&am_buffer[0])
			AM_addMark()
		case AM_CLEARMARKKEY:
			AM_clearMarks()
			plr.message = AMSTR_MARKSCLEARED
		case:
			am_cheatstate = 0
			rc = false
		}
		if deathmatch == 0 && cht_CheckCheat(&cheat_amap, u8(ev.data1)) != 0 {
			rc = false
			cheating = (cheating + 1) % 3
		}
	} else if ev.type == .ev_keyup {
		rc = false
		switch ev.data1 {
		case AM_PANRIGHTKEY:
			if followplayer == 0 { m_paninc.x = 0 }
		case AM_PANLEFTKEY:
			if followplayer == 0 { m_paninc.x = 0 }
		case AM_PANUPKEY:
			if followplayer == 0 { m_paninc.y = 0 }
		case AM_PANDOWNKEY:
			if followplayer == 0 { m_paninc.y = 0 }
		case AM_ZOOMOUTKEY, AM_ZOOMINKEY:
			mtof_zoommul = FRACUNIT
			ftom_zoommul = FRACUNIT
		}
	}

	return rc
}

AM_changeWindowScale :: proc() {
	scale_mtof = FixedMul(scale_mtof, mtof_zoommul)
	scale_ftom = FixedDiv(FRACUNIT, scale_mtof)

	if scale_mtof < min_scale_mtof {
		AM_minOutWindowScale()
	} else if scale_mtof > max_scale_mtof {
		AM_maxOutWindowScale()
	} else {
		AM_activateNewScale()
	}
}

AM_doFollowPlayer :: proc() {
	if f_oldloc.x != plr.mo.x || f_oldloc.y != plr.mo.y {
		m_x = FTOM(MTOF(plr.mo.x)) - m_w/2
		m_y = FTOM(MTOF(plr.mo.y)) - m_h/2
		m_x2 = m_x + m_w
		m_y2 = m_y + m_h
		f_oldloc.x = plr.mo.x
		f_oldloc.y = plr.mo.y
	}
}

AM_updateLightLev :: proc() {
	if amclock > am_nexttic {
		lightlev = am_litelevels[am_litelevelscnt]
		am_litelevelscnt += 1
		if am_litelevelscnt == len(am_litelevels) {
			am_litelevelscnt = 0
		}
		am_nexttic = amclock + 6 - (amclock % 6)
	}
}

AM_Ticker :: proc() {
