G_CheckDemoStatus :: proc() -> boolean {
	if timingdemo {
		endtime := I_GetTime()
		I_Error("timed %i gametics in %i realtics", i32(gametic), i32(endtime - starttime))
	}

	if demoplayback {
		if singledemo {
			I_Quit()
		}

		Z_ChangeTag(demobuffer, PU_CACHE)
		demoplayback = false
		netdemo = false
		netgame = false
		deathmatch = 0
		playeringame[1] = false
		playeringame[2] = false
		playeringame[3] = false
		respawnparm = false
		fastparm = false
		nomonsters = false
		consoleplayer = 0
		D_AdvanceDemo()
		return true
	}

	if demorecording {
		demo_p[0] = DEMOMARKER
		demo_p = &demo_p[1]
		M_WriteFile(cstring(&demoname[0]), demobuffer, int(uintptr(demo_p) - uintptr(demobuffer)))
		Z_Free(demobuffer)
		demorecording = false
		I_Error("Demo %s recorded", &demoname[0])
	}

	return false
}
