				mo.momy = 0
			}
		}

		if xmove == 0 && ymove == 0 {
			break
		}
	}

	if player != nil && (player.cheats & CF_NOMOMENTUM) != 0 {
		mo.momx = 0
		mo.momy = 0
		return
