			}
			si := &sides[li.sidenum[j]]
			si.textureoffset = fixed_t(i32(get[0]) << FRACBITS); get = &get[1]
			si.rowoffset = fixed_t(i32(get[0]) << FRACBITS); get = &get[1]
			si.toptexture = get[0]; get = &get[1]
