sides: [^]side_t

bmapwidth: int
bmapheight: int
blockmap: [^]i16
blockmaplump: [^]i16
bmaporgx: fixed_t
bmaporgy: fixed_t
blocklinks: [^]^mobj_t

rejectmatrix: [^]byte

MAX_DEATHMATCH_STARTS :: 10
