// Based on id Software's linuxdoom-1.10 (GNU GPL)
package main

import "core:c/libc"

FIELDOFVIEW :: 2048

viewangleoffset: angle_t
validcount: int = 1

fixedcolormap: [^]lighttable_t

centerx: int
centery: int

centerxfrac: fixed_t
centeryfrac: fixed_t
projection: fixed_t

framecount: int
sscount: int
linecount: int
loopcount: int

viewx: fixed_t
viewy: fixed_t
viewz: fixed_t

viewangle: angle_t

viewcos: fixed_t
viewsin: fixed_t

viewplayer: ^player_t

detailshift: int

clipangle: angle_t

viewangletox: [FINEANGLES / 2]int
xtoviewangle: [SCREENWIDTH + 1]angle_t

finecosine: [^]fixed_t = &finesine[FINEANGLES / 4]

scalelight: [LIGHTLEVELS][MAXLIGHTSCALE][^]lighttable_t
scalelightfixed: [MAXLIGHTSCALE][^]lighttable_t
zlight: [LIGHTLEVELS][MAXLIGHTZ][^]lighttable_t

extralight: int

