	name: [9]u8

	for i := 0; i < numlumps; i += 1 {
		ptr := lumpcache[i]
		ch: int
		if ptr == nil {
			ch = int(' ')
			continue
		} else {
			block := (^memblock_t)(uintptr(ptr) - size_of(memblock_t))
			if block.tag < PU_PURGELEVEL {
