		libc.memcpy(&name[0], &lumpinfo[i].name[0], 8)
		j := 0
		for ; j < 8; j += 1 {
			if name[j] == 0 {
				break
			}
		}
		for ; j < 8; j += 1 {
			name[j] = ' '
		}
		libc.fprintf(f, "%s ", &name[0])
		for j = 0; j < profilecount; j += 1 {
			libc.fprintf(f, "    %c", i32(w_profile_info[i][j]))
		}
