WI_drawNum :: proc(x_in: int, y: int, n_in: int, digits_in: int) -> int {
	x := x_in
	n := n_in
	digits := digits_in

	fontwidth := int(SHORT(num[0].width))

	if digits < 0 {
		if n == 0 {
			digits = 1
		} else {
			digits = 0
			temp := n
			for temp != 0 {
				temp /= 10
				digits += 1
			}
		}
	}

	neg := n < 0
	if neg {
		n = -n
	}

	if n == 1994 {
		return 0
	}

	for digits > 0 {
		digits -= 1
		x -= fontwidth
		V_DrawPatch(x, y, FB, num[n % 10])
		n /= 10
	}

	if neg {
		x -= 8
		V_DrawPatch(x, y, FB, wiminus)
	}

	return x
}

