WI_initNetgameStats :: proc() {
	wi_state = .StatCount
	acceleratestage = 0
	ng_state = 1
	cnt_pause = TICRATE

	for i := 0; i < MAXPLAYERS; i += 1 {
		if !playeringame[i] {
			continue
		}
		cnt_kills[i] = 0
		cnt_items[i] = 0
		cnt_secret[i] = 0
		cnt_frags[i] = 0
		dofrags += WI_fragSum(i)
	}

	dofrags = dofrags != 0 ? 1 : 0
	WI_initAnimatedBack()
}

WI_updateNetgameStats :: proc() {
	WI_updateAnimatedBack()

	if acceleratestage != 0 && ng_state != 10 {
		acceleratestage = 0
		for i := 0; i < MAXPLAYERS; i += 1 {
			if !playeringame[i] {
				continue
			}
			cnt_kills[i] = (plrs[i].skills * 100) / wbs.maxkills
			cnt_items[i] = (plrs[i].sitems * 100) / wbs.maxitems
			cnt_secret[i] = (plrs[i].ssecret * 100) / wbs.maxsecret
			if dofrags != 0 {
				cnt_frags[i] = WI_fragSum(i)
			}
		}
		S_StartSound(nil, int(sfxenum_t.sfx_barexp))
		ng_state = 10
	}

	if ng_state == 2 {
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		stillticking := false
		for i := 0; i < MAXPLAYERS; i += 1 {
			if !playeringame[i] {
				continue
			}
			cnt_kills[i] += 2
			if cnt_kills[i] >= (plrs[i].skills * 100) / wbs.maxkills {
				cnt_kills[i] = (plrs[i].skills * 100) / wbs.maxkills
			} else {
				stillticking = true
			}
		}
		if !stillticking {
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			ng_state += 1
		}
	} else if ng_state == 4 {
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		stillticking := false
		for i := 0; i < MAXPLAYERS; i += 1 {
			if !playeringame[i] {
				continue
			}
			cnt_items[i] += 2
			if cnt_items[i] >= (plrs[i].sitems * 100) / wbs.maxitems {
				cnt_items[i] = (plrs[i].sitems * 100) / wbs.maxitems
			} else {
				stillticking = true
			}
		}
		if !stillticking {
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			ng_state += 1
		}
	} else if ng_state == 6 {
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		stillticking := false
		for i := 0; i < MAXPLAYERS; i += 1 {
			if !playeringame[i] {
				continue
			}
			cnt_secret[i] += 2
			if cnt_secret[i] >= (plrs[i].ssecret * 100) / wbs.maxsecret {
				cnt_secret[i] = (plrs[i].ssecret * 100) / wbs.maxsecret
			} else {
				stillticking = true
			}
		}
		if !stillticking {
			S_StartSound(nil, int(sfxenum_t.sfx_barexp))
			ng_state += 1 + 2 * (dofrags == 0 ? 1 : 0)
		}
	} else if ng_state == 8 {
		if (bcnt & 3) == 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_pistol))
		}
		stillticking := false
		for i := 0; i < MAXPLAYERS; i += 1 {
			if !playeringame[i] {
				continue
			}
			cnt_frags[i] += 1
			fsum := WI_fragSum(i)
			if cnt_frags[i] >= fsum {
				cnt_frags[i] = fsum
			} else {
				stillticking = true
			}
		}
		if !stillticking {
			S_StartSound(nil, int(sfxenum_t.sfx_pldeth))
			ng_state += 1
		}
	} else if ng_state == 10 {
		if acceleratestage != 0 {
			S_StartSound(nil, int(sfxenum_t.sfx_sgcock))
			if gamemode == .commercial {
				WI_initNoState()
			} else {
				WI_initShowNextLoc()
			}
		}
	} else if (ng_state & 1) != 0 {
		cnt_pause -= 1
		if cnt_pause == 0 {
			ng_state += 1
			cnt_pause = TICRATE
		}
	}
}

